import{z as o,x as p,o as t,c as B,q as E,j as n,D as A,d as l,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"FLAN / Alpaca / ShareGPT 谱系","description":"","frontmatter":{"title":"FLAN / Alpaca / ShareGPT 谱系","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/instruction-data-lineage.md","filePath":"llm/instruction-data-lineage.md","lastUpdated":1791063341000}'),h={name:"llm/instruction-data-lineage.md"};function c(d,a,m,F,T,u){const r=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=E('<h1 id="flan-alpaca-sharegpt-谱系" tabindex="-1">FLAN / Alpaca / ShareGPT 谱系 <a class="header-anchor" href="#flan-alpaca-sharegpt-谱系" aria-label="Permalink to &quot;FLAN / Alpaca / ShareGPT 谱系&quot;">​</a></h1><div class="epigraph"><p>指令微调的数据不是「更多网页」，而是把任务写成模型必须遵循的祈使句；谱系决定你在对齐格式、蒸馏教师，还是在模仿真实多轮。</p><footer>—— 对照 Wei 等 FLAN（ICLR 2022）、Taori 等 Stanford Alpaca（2023）、Chiang 等 Vicuna 所用的 ShareGPT（2023）</footer></div><p><a href="/llm/sft-safety-mix">上一课</a>把「微调」课序收在安全数据占 SFT 的比例：扫描出的混合是粗对齐，为的是给 RM / DPO 留两边都能动的初始化。本课打开「SFT、适配与编辑」：缺口变成<strong>拿什么示范去改条件分布</strong>。指令数据有三条至今仍在混用的谱系——把 NLP 任务模板化的 FLAN、用教师模型自举的 Alpaca、从真实 ChatGPT 导出多轮的 ShareGPT。它们不是同一张表的三个版本。后课默认已经分清这三条，再谈<a href="/llm/response-only-loss">仅回复损失</a>与<a href="/llm/chat-template">chat template</a>；不在这里重写 <a href="/llm/lora">LoRA</a> 或<a href="/llm/full-sft-hparams">全参超参</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>预训练最大化网页上的 \\(p(x_{t+1}\\mid x_{\\le t})\\)，用户却把模型当「接到祈使句就应完成任务」的接口。缺口不是再堆 token，而是示范里<strong>谁在下令、完成长什么样</strong>。三种来源把这件事做成三种函数。</p><p>FLAN（Wei 等人，ICLR 2022）把已有监督任务写成统一指令，训练零样本迁移：见过「翻译成德语」就要会「翻译成罗马尼亚语」。Alpaca（Taori 等人，2023）走 <a href="/llm/self-instruct">Self-Instruct</a>：用 text-davinci-003 从 175 条种子扩到 5.2 万，学生是 LLaMA 7B。ShareGPT 是用户把 ChatGPT 对话点分享后的导出，Vicuna（Chiang 等人，2023）用约 7 万轮多轮对话微调。混用而不标明谱系，等于把任务网格、教师蒸馏和真人多轮当成可互换的 epoch。</p><p><span class="marginnote">「自举」在这里指用模型生成数据再训模型：先手写 175 条种子指令，让强教师模型照着扩写出几万条新指令和回答，再拿去教小模型——相当于老师出教材、学生抄教材，教材里的腔调自然全来自老师。「零样本迁移」则是：训练时见过「翻译成德语」，考试时直接考没见过的「翻译成罗马尼亚语」。</span></p><h3 id="谱系决定你在优化哪一个条件" tabindex="-1">谱系决定你在优化哪一个条件 <a class="header-anchor" href="#谱系决定你在优化哪一个条件" aria-label="Permalink to &quot;谱系决定你在优化哪一个条件&quot;">​</a></h3><p>FLAN 的条件是「任务名 + 输入」；完成往往短、可自动评分。Alpaca 的条件是单轮 <code>Instruction</code> / <code>Input</code> / <code>Response</code>，完成口吻像教师模型。ShareGPT 的条件是带角色交替的长前缀，完成必须接得上上一轮助手。三者的最优<a href="/llm/chat-template">模板</a>不同；用 FLAN 表训完却用 ChatML 推理，是谱系被格式抹平后的错位，不是学习率问题。</p><p><span class="marginnote">Chung 等人把 FLAN 扩到 FLAN-T5 / FLAN-PaLM（JMLR 2024）：主张是任务数目与模板多样性在扩，不是把 ShareGPT 式闲聊写进 T5。Alpaca 论文自己写明数据来自专有教师，许可与泄漏是后话，但方法定位是蒸馏，不是「开源指令的第一性原理」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选型先问产品接口，再问表。要零样本任务迁移、有标准答案：优先 FLAN 族与 Super-NaturalInstructions 一类网格，模板与评测一致。要廉价覆盖用户动词、接受教师腔：Self-Instruct / Alpaca，并记录教师型号与过滤阈值。要多轮、工具穿插、真人跑题：ShareGPT 及后续清洗版，但必须按<a href="/llm/chat-template">对话模板</a>重渲染，不能把导出的 Markdown 直接当 token。</p><p>混合可以，但要当<strong>配比</strong>写进配方，而不是 concat 后假装同质。常见配比是：网格任务保技能、精选人或 <a href="/llm/lima">LIMA</a> 式示范定口吻、少量多轮教指代。Ouyang 等人的 <a href="/llm/instructgpt">InstructGPT</a> 用人写示范做 SFT，再进 RLHF；开源谱系常把这一段换成合成或导出，省标注、买偏差。</p>',13)),(t(),n(i,null,{default:A(()=>[s(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%BD%91%E9%A1%B5%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%20--%3E%20F%5B%22FLAN%EF%BC%9A%E4%BB%BB%E5%8A%A1%E6%A8%A1%E6%9D%BF%E5%8C%96%22%5D%0A%20%20W%20--%3E%20A%5B%22Alpaca%EF%BC%9A%E6%95%99%E5%B8%88%E8%87%AA%E4%B8%BE%E5%8D%95%E8%BD%AE%22%5D%0A%20%20W%20--%3E%20S%5B%22ShareGPT%EF%BC%9A%E7%9C%9F%E4%BA%BA%E5%A4%9A%E8%BD%AE%E5%AF%BC%E5%87%BA%22%5D%0A%20%20F%20--%3E%20T%5B%22%E7%BB%9F%E4%B8%80%20chat%20template%20%E5%86%8D%20SFT%22%5D%0A%20%20A%20--%3E%20T%0A%20%20S%20--%3E%20T%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"过滤按谱系分叉。FLAN 查标签与输入是否匹配。Alpaca 查与种子的近重复、空输出、指令–回答矛盾。ShareGPT 查角色字段是否完整、是否把系统提示或工具 JSON 糊进用户段、是否含评测泄漏。条数不是质量；未过滤的 10 万轮可以比 1 万清洗轮更毁格式。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"初学者容易以为「条数越多模型越强」。SFT 阶段改的是条件分布的格式与口吻，1 万条干净、谱系单一的样本往往胜过 10 万条模板错位、角色糊掉的脏数据——脏数据教坏的恰恰是这一阶段最该学的东西。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[l("SFT 学的是渲染后前缀上的条件分布。FLAN 把「任务说明」变成高频前缀，模型学会把说明当程序；未见任务靠说明里的动词泛化，这是 Wei 等人零样本主张的机制。Alpaca 把教师的完成风格写入学生：短列表、客套结尾、拒绝模式都可能是教师的，不是用户的。ShareGPT 把长上下文里的指代与修正写进注意力：用户说「改成更短」，模型必须绑定上一轮答案。三种机制对"),e("a",{href:"/llm/response-only-loss"},"仅回复损失"),l("的敏感点不同——网格任务漏掩码会背题面；多轮漏掩码会模仿用户。")],-1)),(t(),n(i,null,{default:A(()=>[s(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22FLAN%3A%20%E4%BB%BB%E5%8A%A1%E8%AF%B4%E6%98%8E%E6%88%90%E4%B8%BA%E9%AB%98%E9%A2%91%E5%89%8D%E7%BC%80%22%5D%20--%3E%20F1%5B%22%E5%AD%A6%E4%BC%9A%E6%8A%8A%E8%AF%B4%E6%98%8E%E5%BD%93%E7%A8%8B%E5%BA%8F%E6%89%A7%E8%A1%8C%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E6%9C%AA%E8%A7%81%E4%BB%BB%E5%8A%A1%E9%9D%A0%E5%8A%A8%E8%AF%8D%E6%B3%9B%E5%8C%96%22%5D%0A%20%20A%5B%22Alpaca%3A%20%E6%95%99%E5%B8%88%E7%9A%84%E5%AE%8C%E6%88%90%E6%96%87%E6%9C%AC%22%5D%20--%3E%20A1%5B%22%E7%9F%AD%E5%88%97%E8%A1%A8%E4%B8%8E%E5%AE%A2%E5%A5%97%E7%BB%93%E5%B0%BE%E8%A2%AB%E6%A8%A1%E4%BB%BF%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E5%AD%A6%E5%88%B0%E6%95%99%E5%B8%88%E8%85%94%2C%20%E4%B8%8D%E6%98%AF%E7%94%A8%E6%88%B7%E5%81%8F%E5%A5%BD%22%5D%0A%20%20S%5B%22ShareGPT%3A%20%E9%95%BF%E5%A4%9A%E8%BD%AE%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%20--%3E%20S1%5B%22%E6%8C%87%E4%BB%A3%E4%B8%8E%E4%BF%AE%E6%AD%A3%E8%A6%81%E7%BB%91%E5%AE%9A%E5%89%8D%E8%BD%AE%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%AD%A6%E4%BC%9A%E6%8E%A5%E4%BD%8F%E4%B8%8A%E4%B8%80%E8%BD%AE%E5%8A%A9%E6%89%8B%E7%AD%94%E6%A1%88%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">后课用到的约定：说到「Alpaca 格式」指单轮 Instruction 字段；说到「对话 SFT」指消息列表经 chat template 渲染。不要用「指令数据」一词同时覆盖三者。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>谱系不是时间线上的淘汰。2024 年以后的配方仍在混：数学用网格与合成解答，助手口吻用精选对话，工具用协议化轨迹。边界是：教师蒸馏继承教师的安全与谄媚；导出对话继承 UI 与隐私；任务网格几乎不教多轮。许可上，Alpaca 与早期 ShareGPT 都不能当「可商用金标准」。评测上，MMLU 偏 FLAN 族，人评开放生成偏 ShareGPT / LIMA 族；只报其中一个，会选出错误配比。</p><p><span class="marginnote">这一步如果做错，评测会自证循环：拿 MMLU（偏 FLAN 族）选模型，选出的可能只是任务网格背得好；开放聊天本该用 ShareGPT / LIMA 式人评来看。混合配方的评测必须两条轴都测，否则你优化的是考纲，不是产品。</span></p><p>全参还是 <a href="/llm/lora">LoRA</a> 不改变谱系选择；只改变你敢用多脏的数据——适配器过拟合脏多轮更快。超参见<a href="/llm/full-sft-hparams">全参学习率与批次</a>，本课不扫 \\(\\eta\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指令数据有三条谱系：FLAN 任务网格、Alpaca 式教师自举、ShareGPT 式真人多轮。</li><li>谱系决定条件前缀与最优模板；混用必须写成配比。</li><li>FLAN 优化零样本任务迁移；Alpaca 蒸馏教师腔；ShareGPT 教多轮指代。</li><li>过滤、许可、评测轴都随谱系变，不能只比条数。</li><li>后课默认已分清谱系，再谈损失掩码与打包。</li><li>出处：Wei 等，FLAN，ICLR 2022；Chung 等，Scaling Instruction-Finetuned LMs，JMLR 2024；Taori 等，Stanford Alpaca，2023；Chiang 等，Vicuna / ShareGPT，2023。</li></ul>',7))])}const D=o(h,[["render",c]]);export{f as __pageData,D as default};
